def main():
    try: locale.setlocale(locale.LC_ALL, 'fr_FR.UTF-8')
    except: pass
    inject_custom_css()

    if "hse_affiche" not in st.session_state: st.session_state.hse_affiche = False
    if not st.session_state.hse_affiche:
        c = random.choice(["Port obligatoire des EPI avant toute intervention.", "Aucun travail n'est plus urgent que la sécurité.", "Ne jamais intervenir sur un équipement en marche.", "Baliser et sécuriser la zone de travail.", "Signaler immédiatement toute situation dangereuse."])
